mapper.select:
select i.item_id, i.item_cd, i.proc_type, i.unit_cd
  from mst_item i
 where i.item_id in #{id}

select 
  from aps_mrp m left join aps_mps s on s.mps_id = m.mps_id
 where m.calculated_at >= #{from} and m.calculated_at < #{to}
   and m.plant_cd = #{plantCd}
 order by m.calculated_at desc, m.mrp_id desc
 limit #{limit}

select 
  from aps_mrp m left join aps_mps s on s.mps_id = m.mps_id
 where m.mrp_id = #{id}

select 
  from aps_mrp_elem e join mst_item i on i.item_id = e.item_id
 where e.mrp_id = #{mrpId} and e.kind in ('MPS', 'PLAN')
   and e.item_id = #{itemId}
   and e.kind = #{kind}
 order by i.item_cd, e.elem_date, e.elem_seq
 limit #{limit}

select 
  from aps_mrp_elem e join mst_item i on i.item_id = e.item_id
 where e.mrp_id = #{mrpId}
   and e.item_id = #{itemId}

       and e.elem_seq in #{s}

 order by e.elem_date, case when e.dir = 'S' then 0 else 1 end, e.elem_seq

select p.demand_seq, p.supply_seq, trim_scale(p.qty)::text as qty
  from aps_mrp_peg p
 where p.mrp_id = #{mrpId}
   and (


           p.demand_seq in #{s}

       false

   or


           p.supply_seq in #{s}

       false

   )
 order by p.demand_seq, p.supply_seq
